int fst_draw(const struct _fst *fst, FILE *fout)
{
    struct _state *state;
    struct _arc *arc;
    fprintf(fout, "%s", header);
    for (uint32_t s = 0; s < fst->n_states; ++s)
    {
        state = &fst->states[s];
        if (!state->final)
        {
            fprintf(fout,
                    "\t%"
                    "u"
                    " [label = \"%"
                    "u"
                    "\", shape = circle, style = %s ];\n",
                    s, s, s == fst->start ? "filled" : "solid");
        }
        else
        {
            fprintf(fout,
                    "\t%"
                    "u"
                    " [label = \"%"
                    "u"
                    "\", shape = doublecircle, style = filled ];\n",
                    s, s);
        }
        for (uint32_t a = 0; a < state->n_arcs; ++a)
        {
            arc = &state->arcs[a];
            fprintf(fout,
                    "\t\t%"
                    "u"
                    " -> %"
                    "u"
                    " [ label = \"%"
                    "u"
                    ":%"
                    "u"
                    "/%g\" ];\n",
                    s, arc->state, arc->ilabel, arc->olabel, arc->weight);
        }
    }
    fprintf(fout, "%s", footer);
    return 0;
}

