    struct _sr sr = sr_get(fst->sr_type);
    itrans = (ist == ((void *)0) ? trn : trt);
    otrans = (ost == ((void *)0) ? trn : trt);
    strans = (sst == ((void *)0) ? trn : trt);
    if (sscanf(buf, "%s\t%s\t%s\t%s\t%f", sa, sb, li, lo, &w) == 5)
    {
        _sa = strans(sa, sst);
        _sb = strans(sb, sst);
        _li = itrans(li, ist);
        _lo = otrans(lo, ost);
        if (_sa == -1 || _sb == -1 || _li == -1 || _lo == -1)
            return -1;
        _add_arc(fst, _sa, _sb, _li, _lo, w);
    }
    else
    {
        if (sscanf(buf, "%s\t%s\t%s\t%s", sa, sb, li, lo) == 4)
        {
            _sa = strans(sa, sst);
