functions.fst_compile:
struct _fst *fst_compile(struct _fst *fst, FILE *fin, struct _symt *ist, struct _symt *ost, struct _symt *sst,
                         int is_acc)
{
    char p[0xffff];
    size_t line = 1;
    int res = 0;
    while (fgets(p, sizeof(p), fin) != ((void *)0))
    {
        ++line;
        if (is_acc == 0)
            res = _parse_line_sym(fst, p, ist, ost, sst);
        else
            res = _parse_line_sym_acc(fst, p, ist, sst);
        if (res != 0)
        {
            fprintf(stderr, "Invalid input line %zd: %s", line, p);
            exit(1);
        }
    }
    size_t start_state;
    if (sst != ((void *)0))
    {
        if ((start_state = symt_getr(sst, "<start>")) != -1)
            fst->start = start_state;
    }
    return fst;
}

functions.fst_compile_str:
struct _fst *fst_compile_str(struct _fst *fst, const char *str)
{
    char p[0xffff];
    char *tok;
    size_t line = 1;
    strcpy(p, str);
    do
    {
        if (line == 1)
            tok = strtok(p, "\n");
        else
        {
            tok = strtok(((void *)0), "\n");
        }
        if (tok)
            if (_parse_line(fst, tok) != 0)
            {
                fprintf(stderr, "Invalid input line %zd: %s\n", line, tok);
                exit(1);
            }
        ++line;
    } while (tok);
    return fst;
}

