    fst->n_max = 0;
    fst->start = 0;
    fst->flags = 0;
    fst->states = ((void *)0);
    return fst;
}

functions.fst_add_state:
uint32_t fst_add_state(struct _fst *fst)
{
    struct _state *state;
    ++fst->n_states;
    if (fst->n_states > fst->n_max)
    {
        fst->n_max = fst->n_states * 2;
        fst->states = realloc(fst->states, sizeof(struct _state) * fst->n_max);
    }
    state = &fst->states[fst->n_states - 1];
    state->n_arcs = 0;
    state->n_max = 0;
    state->final = 0;
    state->weight = 0;
    state->arcs = ((void *)0);
    return fst->n_states - 1;
}

functions.fst_add_arc:
uint32_t fst_add_arc(struct _fst *fst, uint32_t src, uint32_t dst, uint32_t il, uint32_t ol, float weight)
{
    struct _arc *arc;
    struct _state *state = &fst->states[src];
    ++state->n_arcs;
    if (state->n_arcs > state->n_max)
    {
        state->n_max = state->n_arcs * 2;
        state->arcs = realloc(state->arcs, sizeof(struct _arc) * state->n_max);
    }
    arc = &state->arcs[state->n_arcs - 1];
    arc->state = dst;
    arc->ilabel = il;
    arc->olabel = ol;
    arc->weight = weight;
    return state->n_arcs - 1;
}

