        state = fst->states + s;
        if (state->arcs != ((void *)0))
            free(state->arcs);
    }
    if (fst->states != ((void *)0))
        free(fst->states);
    fst->n_states = 0;
    fst->n_max = 0;
    fst->states = ((void *)0);
