}

functions.fst_relabel:
void fst_relabel(struct _fst *fst, uint32_t old, uint32_t new, int dir)
{
    struct _state *state;
    struct _arc *arc;
    for (uint32_t s = 0; s < fst->n_states; ++s)
    {
        state = &fst->states[s];
        for (uint32_t a = 0; a < state->n_arcs; ++a)
        {
            arc = &state->arcs[a];
            if (dir == 0)
            {
                if (arc->ilabel == old)
                    arc->ilabel = new;
            }
            else
            {
                if (arc->olabel == old)
                    arc->olabel = new;
            }
        }
    }
}

