functions.fst_print:
void fst_print(const struct _fst *fst)
{
    struct _state state;
    struct _arc arc;
    uint32_t s;
    uint32_t a;
    struct _queue *finals = queue_create(sizeof(uint32_t));
    for (s = 0; s < fst->n_states; ++s)
    {
        state = fst->states[s];
        for (a = 0; a < state.n_arcs; ++a)
        {
            arc = state.arcs[a];
            printf("%"
                   "u"
                   "\t%"
                   "u"
                   "\t%"
                   "u"
                   "\t%"
                   "u"
                   "\t%.5f\n",
                   s, arc.state, arc.ilabel, arc.olabel, arc.weight);
        }
        if (state.final == 1)
        {
            queue_enque(finals, &s);
        }
    }
    while (queue_deque(finals, &s) != ((void *)0))
    {
        state = fst->states[s];
        printf("%"
               "u"
               "\t%f\n",
               s, state.weight);
    }
    queue_remove(finals);
}

functions.trn:
static char *trn(struct _symt *st, size_t id, char *token)
{
    sprintf(token, "%zu", id);
    return token;
}

functions.trt:
static char *trt(struct _symt *st, size_t id, char *token)
{
    char *t = symt_get(st, id);
    if (t == ((void *)0))
    {
        token = ((void *)0);
        fprintf(stderr, "Unknown token: %s\n", token);
    }
    else
    {
        strcpy(token, t);
    }
    return token;
}

functions.fst_print_sym:
void fst_print_sym(const struct _fst *fst, struct _symt *ist, struct _symt *ost, struct _symt *sst)
{
    struct _state state;
    struct _arc arc;
    token_t sa, sb, li, lo;
    rtrans_f strans, itrans, otrans;
    uint32_t s;
    uint32_t a;
    itrans = (ist == ((void *)0) ? trn : trt);
    otrans = (ost == ((void *)0) ? trn : trt);
    strans = (sst == ((void *)0) ? trn : trt);
    struct _queue *finals = queue_create(sizeof(uint32_t));
    for (s = 0; s < fst->n_states; ++s)
    {
        state = fst->states[s];
        for (a = 0; a < state.n_arcs; ++a)
        {
            arc = state.arcs[a];
            strans(sst, s, sa);
            strans(sst, arc.state, sb);
            itrans(ist, arc.ilabel, li);
            otrans(ost, arc.olabel, lo);
            if (sa == ((void *)0) || sb == ((void *)0) || li == ((void *)0) || lo == ((void *)0))
            {
                fprintf(stderr, "Invalid symbol\n");
                exit(1);
            }
            printf("%s\t%s\t%s\t%s\t%.5f\n", sa, sb, li, lo, arc.weight);
        }
        if (state.final == 1)
        {
            queue_enque(finals, &s);
        }
    }
    while (queue_deque(finals, &s) != ((void *)0))
    {
        state = fst->states[s];
        strans(sst, s, sa);
        if (sa == ((void *)0))
        {
            fprintf(stderr, "Invalid symbol\n");
            exit(1);
        }
        printf("%s\t%f\n", sa, state.weight);
    }
    queue_remove(finals);
}
